void PndMasterRunSim::UseFtfGenerator(TString ftfData)
{
  // if ( strncmp(fName,"TGeant4",7 ) == 0 ) LOG(fatal) << "FTF does not run with Geant4 !!!"  ;
  if (ftfData.Contains(".root")) {
    LOG(info) << "Using PndFtfGenerator with input file " << ftfData;
