 * @brief Class for accessing PID detector information of MVD.
 * @author Sarah Gaiser <gaiser@hiskp.uni-bonn.de>, HISKP Bonn
 * @version 1.0
 * @date Jan 2021
 */
class PndPidMvdInfo : public PndPidTrackingDetectorInfo {
 public:
  PndPidMvdInfo();  ///< Default constructor.
  ~PndPidMvdInfo(); ///< default destructor.

  void SetFast(Bool_t fast_mode) { fFast = fast_mode; };
  void Reset();

  /**
   * @brief Fill detector hit TCAs and adjust detector mode.
   * @param manager Needed to get fMvdHitsStrip and fMvdHitsPixel TCAs of event.
   * @return Adjusted detector mode.
   */
  virtual Int_t SetDetectorHits(FairRootManager *manager);

  /**
   * @brief Setup FTS info.
   * @param manager Needed to get all relevant TCAs of event.
   * @param propagator Propagator to be used in track-hit correlation.
   * @param params Set of detector and track parameters that is passed from PndPidCorrelator.
   * @return kTRUE if successful.
   */
  Bool_t Setup(FairRootManager *manager, PndPropagator *propagator, PndPidDetectorParams::DetectorParams *params);

  /**
   * @brief Add MVD information to PidCandidate.
   * @details Get information on detector hits and energy loss from track.
   * @param track One of the detected tracks in current event.
   * @param pidCand PidCandidate belonging to track.
   * @return kTRUE if successful.
   */
  virtual Bool_t GetInfo(PndTrack *track, PndPidCandidate *pidCand);

 protected:
  TClonesArray *fMvdHitsStrip = nullptr;                    ///< Mvd strip detector hits TCA.
  TClonesArray *fMvdHitsPixel = nullptr;                    ///< Mvd pixel detector hits TCA.
  std::unique_ptr<PndGeoHandling> fGeoH{nullptr}; ///< Handler for MVD geometry.

  Double_t fMvdELoss = 0; ///< Energy Loss in MVD.
  Double_t fMvdPath = 0;  ///< MVD path crossed by the particle.
  Int_t fMvdHitCount = 0; ///< Number of mvd hits.

  Bool_t fFast; ///< if kTRUE add only number of hits in MVD.

  ClassDef(PndPidMvdInfo, 1);
};

