  SensName[3] = "/TS_1/TTVol_0/TTSingle_0/StripActiveTS4a_0";
  SensName[4] = "/TS_1/TTVol_0/TTSingle_0/StripActiveTS4b_0";
  SensName[5] = "/TS_1/TTVol_0/TTDouble_0/StripActiveTD2_0";

