ErrCode DecayTreeFitter::RecoPhoton::initParPhoton(FitParams *fitparams, const TVector3 &motherpos) const
{
  if (fitvertex) {
    TVector3 dx(m_m(0) - motherpos.x(), m_m(1) - motherpos.y(), m_z - motherpos.z());
    double l = dx.Mag();

    // get the energy
    double energy = m_m(2);

    // assign the momentum
    int momindex = momIndex();
    fitparams->par(momindex + 0) = energy * dx.x() / l;
    fitparams->par(momindex + 1) = energy * dx.y() / l;
    fitparams->par(momindex + 2) = energy * dx.z() / l;
  }
  else if (addfreeZ) {
    TVector3 dx(m_m(0) - motherpos.x(), m_m(1) - motherpos.y(), m_z - motherpos.z());
    double l = dx.Mag();

    // get the energy
    double energy = m_m(2);

    // assign the momentum
    int momindex = momIndex();
    fitparams->par(momindex + 0) = energy * dx.x() / l;
    fitparams->par(momindex + 1) = energy * dx.y() / l;
    fitparams->par(momindex + 2) = energy * dx.z() / l;
  }
  else {
    // assign the momentum
    // if we have no primary vertex we take px, py and pz from the reconstructed candidate
    int momindex = momIndex();
    fitparams->par(momindex + 0) = m_m(0);
    fitparams->par(momindex + 1) = m_m(1);
    fitparams->par(momindex + 2) = m_m(2);
  }
  return ErrCode();
}

