ErrCode DecayTreeFitter::RecoPhoton::initPar2(FitParams *fitparams)
{
  if (vtxverbose > 5) {
    std::cout << "RecoPhoton::initPar2: - " << std::endl;
  }
  // calculate the direction
  if (fitvertex) {
    int posindexmother = mother()->posIndex();
    TVector3 motherpos(fitparams->par(posindexmother + 0), fitparams->par(posindexmother + 1), fitparams->par(posindexmother + 2));
    return initParPhoton(fitparams, motherpos);
  }
  else if (addfreeZ) {
    int posindexmother = mother()->posIndex();
    TVector3 motherpos(0, 0, fitparams->par(posindexmother));
    return initParPhoton(fitparams, motherpos);
  } 
  else {
    TVector3 motherpos(0, 0, 0);
    return initParPhoton(fitparams, motherpos);
  }
}

ErrCode DecayTreeFitter::RecoPhoton::initCov(FitParams *fitparams) const
{
  int momindex = momIndex();
  if (fitvertex) {
    double varEnergy = m_V(2, 2);
    const double factor = 1000;
    for (int row = 0; row < 3; row++)
      fitparams->cov()(momindex + row, momindex + row) = factor * varEnergy;
  }
  else if (addfreeZ) {
    const double factor = 1000;
    for (int row = 0; row < 3; row++) {
      for (int col = 0; col < 3; col++) {
        fitparams->cov()(momindex + col, momindex + row) = factor * m_par_V(col, row); // add off-diagonal entries
      } 
    }
  }
  else {
    const double factor = 1000;
    for (int row = 0; row < 3; row++) {
      for (int col = 0; col < 3; col++) {
        fitparams->cov()(momindex + col, momindex + row) = factor * m_V(col, row); // add off-diagonal entries
      } 
    }
  }
  return ErrCode();
}

