  }
  else {
    // if we have no primary vertex we take px, py and pz from the reconstruction
    PndPidCandidate *rec = particle()->GetRecoCandidate();
    m_m(0) = rec->GetMomentum().X(); // px
    m_m(1) = rec->GetMomentum().Y(); // py
    m_m(2) = rec->GetMomentum().Z(); // pz
    m_z = rec->GetEnergy();          // E
