ErrCode DecayTreeFitter::RecoPhoton::projectRecoConstraint(const FitParams *fitparams, Projection &p) const
{

  ErrCode status;

  if (fitvertex) {
    // residual of photon:
    // r(0-2) = motherpos + mu * photon momentum - cluster position
    // r(3)   = |momentum| - cluster energy
    // mu is calculated from the 'chi2-closest approach' (see below)

    // calculate the total momentum and energy:
    int momindex = momIndex();
    double px = fitparams->par()(momindex + 0);
    double py = fitparams->par()(momindex + 1);
    double pz = fitparams->par()(momindex + 2);
    double m = pdtMass(); // could be non-zero for mergedpi0

    double energy = std::sqrt(px * px + py * py + pz * pz + m * m);
    double dedpx = px / energy;
    double dedpy = py / energy;
    double dedpz = pz / energy;

    double tx = px / pz;
    double ty = py / pz;
    double dtxdpx = 1 / pz;
    double dtxdpz = -tx / pz;
    double dtydpy = 1 / pz;
    double dtydpz = -ty / pz;

    // calculate dX = Xc - Xmother
    int posindex = mother()->posIndex();

    double dz = m_z - fitparams->par(posindex + 2);
    double dx = m_m(0) - fitparams->par(posindex + 0) - dz * tx;
    double dy = m_m(1) - fitparams->par(posindex + 1) - dz * ty;
    double dE = m_m(2) - energy;

    p.r(0) = dx;
    p.r(1) = dy;
    p.r(2) = dE;

    // calculate the projection matrix
    // first the 'position' part

    // derivative of position to position of mother
    p.H(0, posindex + 0) = -1;
    p.H(1, posindex + 1) = -1;
    p.H(0, posindex + 2) = tx;           // this derivative was missing before 
    p.H(1, posindex + 2) = ty;           // this derivative was missing before

    // derivative to position to 3-momentum
    p.H(0, momindex + 0) = -dz * dtxdpx;
    p.H(0, momindex + 2) = -dz * dtxdpz;
    p.H(1, momindex + 1) = -dz * dtydpy;
    p.H(1, momindex + 2) = -dz * dtydpz;

    // derivative of momentum to 3-momentum
    p.H(2, momindex + 0) = -dedpx;
    p.H(2, momindex + 1) = -dedpy;
    p.H(2, momindex + 2) = -dedpz;

    // error
    for (int irow = 0; irow < 3; irow++)
      for (int icol = 0; icol < 3 /*=irow*/; icol++)
        p.Vfast(irow, icol) = m_V(irow, icol);
    if (vtxverbose > 6) {
      std::cout << "RecoPhoton::projectRecoConstraint(): projection is:" << posindex << std::endl;
      std::cout << "r ";
      p.r().Print();
      std::cout << "V ";
      p.V().Print();
      std::cout << "H ";
      RhoCalculationTools::PrintMatrix(p.H());
    }
  }
  else if (addfreeZ) {
    // for the case of an additional free parameter in z direction we exchange x,y in the residual
    // for y and z to adjust the parameter value for the free parameter z

    // residual of photon:
    // r(0-2) = motherpos + mu * photon momentum - cluster position
    // r(3)   = |momentum| - cluster energy
    // mu is calculated from the 'chi2-closest approach' (see below)

    // calculate the total momentum and energy:
    int momindex = momIndex();
    double px = fitparams->par()(momindex + 0);
    double py = fitparams->par()(momindex + 1);
    double pz = fitparams->par()(momindex + 2);
    double m = pdtMass(); // could be non-zero for mergedpi0

    double energy = std::sqrt(px * px + py * py + pz * pz + m * m);
    double dedpx = px / energy;
    double dedpy = py / energy;
    double dedpz = pz / energy;

    double tx = px / pz;
    double ty = py / pz;
    double dtxdpx = 1 / pz;
    double dtxdpz = -tx / pz;
    double dtydpy = 1 / pz;
    double dtydpz = -ty / pz;

    // calculate dX = Xc - Xmother
    int posindex = mother()->posIndex();

    double dz = m_z - fitparams->par(posindex);                   // a bit confusing, but m_z is now used for x and m_m for y,z,E
    double dx = m_m(0) - dz * tx;      // furthermore the motherpos for x and y are set to 0
    double dy = m_m(1) - dz * ty;
    double dE = m_m(2) - energy;

    p.r(0) = dx;
    p.r(1) = dy;
    p.r(2) = dE;

    // calculate the projection matrix
    // first the 'position' part

    // derivative of position to position of mother
    p.H(0, posindex + 0) = tx;       // the z-position is the only motherpos not fixed to 0 
    p.H(1, posindex + 0) = ty;       // the z-position is the only motherpos not fixed to 0      

    // derivative to position to 3-momentum
    p.H(0, momindex + 0) = -dz * dtxdpx;
    p.H(0, momindex + 2) = -dz * dtxdpz;
    p.H(1, momindex + 1) = -dz * dtydpy;
    p.H(1, momindex + 2) = -dz * dtydpz;

    // derivative of momentum to 3-momentum
    p.H(2, momindex + 0) = -dedpx;
    p.H(2, momindex + 1) = -dedpy;
    p.H(2, momindex + 2) = -dedpz;

    // error
    for (int irow = 0; irow < 3; irow++)
      for (int icol = 0; icol < 3 /*=irow*/; icol++)
        p.Vfast(irow, icol) = m_V(irow, icol);

    if (vtxverbose > 6) {
      std::cout << "RecoPhoton::projectRecoConstraint(): projection is:" << posindex << std::endl;
      std::cout << "r ";
      p.r().Print();
      std::cout << "V ";
      p.V().Print();
      std::cout << "H ";
      RhoCalculationTools::PrintMatrix(p.H());
    }
  }
  else{
    // if we have no primary vertex we take px, py and pz from the reconstruction
    
    // residual of photon without vertex positions:
    // r(0-2) = original photon momentum - fitted photon momentum

    // In our case this kinematic projection constraint is really easy, 
    // given that our final state particles neither have a single daughter, nor an energy
    // and we are not interested in adjusting any vertex positions,
    // which majorly simplifies the derivatives we need to calculate
    int momindex = momIndex();
    for (int imom = 0; imom < 3; imom++) {
      p.r(imom) = m_m(imom) - fitparams->par()(momindex + imom); 
      p.H(imom, momindex + imom) = -1;
    }

    // error
    for (int irow = 0; irow < 3; irow++)
      for (int icol = 0; icol < 3; icol++)
        p.Vfast(irow, icol) = m_V(irow, icol);
  }

  return status;
}

