void PndApolloniusTripletTrackFinderTask::Exec(Option_t *)
{
  LOG(DEBUG) << "*** Event: " << ioman->GetEntryNr();

  for (auto it = fBranchMap.begin(); it != fBranchMap.end(); it++) {
