// Macro for running FtsTrackFinder task
// to run the macro:
// root  ftsTrackFinder.C or in root session root > .x  ftsTrackFinder.C

int ftsTrackFinder(Int_t nEvents = 0)
{
  // -----   OPTIONS   ------------------------------------------------------
  TString parAsciiFile = "all.par";
  TString prefix = "evtcomplete";
  TString input = "box:type(13,4):p(1,5):tht(0,10)";
  TString output = "reco_fts";
  TString simFriend = "sim";
  TString digiFriend = "digi";

  // -----   RUNNER SETUP   --------------------------------------------
  PndMasterRunAna *runner = new PndMasterRunAna();
  runner->SetInput(input);
  runner->SetOutput(output);
  runner->AddFriend(simFriend);
  runner->AddFriend(digiFriend);
  runner->SetParamAsciiFile(parAsciiFile);
  runner->Setup(prefix);

  // -----   TRACKING TASK SETUP   --------------------------------------------
  PndFtsTrackFinderTask *tracker_task = new PndFtsTrackFinderTask();
  tracker_task->SetOutputBranchName("FtsTrackFinder");
  tracker_task->SetMomentumEstimationMethod(PndFtsTrackFinder::PndFtsMomEstMethod::TANGENT);
  tracker_task->SetPersistency(true);
  tracker_task->SetVerbose(0);
  runner->AddTask(tracker_task);

  // -----   INITIALISE AND RUN   --------------------------------------------
  runner->Init();
  runner->Run(0, nEvents);
  runner->Finish();

  return 0;
}

