  trackFts->AddBranchName("FTSHit");
  trackFts->AddBranchName("MVDHitsPixel");
  trackFts->AddBranchName("MVDHitsStrip");
  trackFts->SetRelativeMomentumSmearing(0.05);
  trackFts->SetVertexSmearing(0.05, 0.05, 0.05);
  trackFts->SetTrackingEfficiency(1.);
  trackFts->SetOutputBranchName("FtsIdealTrack");
  trackFts->SetPersistence(kTRUE);

  if (!fOptions.Contains("gf2")) {
    PndRecoKalmanTask *recoKalmanFwd = nullptr;
    fRun->AddTask(recoKalmanFwd = new PndRecoKalmanTask());
    recoKalmanFwd->SetTrackInBranchName("FtsIdealTrack");
    // recoKalmanFwd->SetTrackInIDBranchName("FtsIdealTrackID");
    recoKalmanFwd->SetTrackOutBranchName("FtsIdealGenTrack");
    recoKalmanFwd->SetBusyCut(50); // CHECK to be tuned
    // recoKalmanFwd->SetIdealHyp(kTRUE);
    // recoKalmanFwd->SetNumIterations(3);
    recoKalmanFwd->SetTrackRep(0); // 0 Geane (default), 1 RK
    //recoKalmanFwd->SetPropagateToIP(kFALSE);
  } else {
    PndRecoKalmanTask2 *recoKalmanFwd = nullptr;
    fRun->AddTask(recoKalmanFwd = new PndRecoKalmanTask2());
    recoKalmanFwd->SetTrackInBranchName("FtsIdealTrack");
    // recoKalmanFwd->SetTrackInIDBranchName("FtsIdealTrackID");
    recoKalmanFwd->SetTrackOutBranchName("FtsIdealGenTrack");
    recoKalmanFwd->SetBusyCut(50); // CHECK to be tuned
                                   // recoKalmanFwd->SetIdealHyp(kTRUE);
    // recoKalmanFwd->SetNumIterations(3);
    // recoKalmanFwd->SetTrackRep(0); // 0 Geane (default), 1 RK
    //recoKalmanFwd->SetPropagateToIP(kFALSE);
  }

  // -----   Intialise and run   --------------------------------------------
  fRun->Init();
  fRun->Run(0, nEvents);
  fRun->Finish();
  return 0;
}

#### Apollonius track finding

Three STT drift measurements define three circles in the transverse plane. The classical Apollonius problem asks for circles tangent to all three. Up to eight geometric solutions can exist because of the internal/external tangency combinations.

The track finder reduces combinatorics by:

- choosing spatially separated inner, middle, and outer hit rows;
- requiring neighbor/topological compatibility;
- imposing azimuthal compatibility;
- growing each candidate with additional compatible hits;
- selecting the populated trajectory that best matches the complete hit pattern.

This avoids a hard nominal-IP constraint and preserves efficiency for displaced vertices.

