#### Apollonius track finding

Three STT drift measurements define three circles in the transverse plane. The classical Apollonius problem asks for circles tangent to all three. Up to eight geometric solutions can exist because of the internal/external tangency combinations.

The track finder reduces combinatorics by:

- choosing spatially separated inner, middle, and outer hit rows;
- requiring neighbor/topological compatibility;
- imposing azimuthal compatibility;
- growing each candidate with additional compatible hits;
- selecting the populated trajectory that best matches the complete hit pattern.

This avoids a hard nominal-IP constraint and preserves efficiency for displaced vertices.

---

### Repository state covered by this README

The current workflow includes:

- distributed target generation with selectable cryopump or no-cryopump profiles;
- displaced-track reconstruction using the Apollonius triplet finder;
- an event-level `event_poca` data product keyed by `event_id`;
- second-pass GEANE propagation to the matching event POCA;
- beam-momentum propagation from JSON configuration into both analysis macros;
- consistent `*_pid_final.root` and `*_ana_final.root` completion sentinels;
- profile-dependent efficiency correction and robustness studies.

---

void PndCurlingTrackFinder::FindTracks()
{

  LOG(DEBUG) << "FindTracks";

  if (fBranchMap.size() == 0) {
    LOG(ERROR) << "No data branches given!";
    return;
  }

  // the steps of the algorithms are numbered like in the description
  fMapHitstoCATracklet = fFunc.GetHitsToCAMap(fCATrackFinder);

  if (fUnassignedSttHits.size() > 3) {
    std::vector<TripletSolution> groupSolutions;
    double fMinDistance = 5.;
    std::map<int, std::vector<std::vector<PndSttHit *>>> tubeStructure = fFunc.GetTubeStructure(fUnassignedSttHits, fGeometryMap, fAllHitsCounter, fIsStrongCurling);
    TripletValues triplets = GetTripletsCurledTracks(tubeStructure);
    // TripletValues triplets = GetTripletsCurledTracks2();
    // std::cout << "Generated Triplets: " << triplets << std::endl;
    std::vector<Triplet> tripletIndices =
      fFunc.ReduceCombinatorics(triplets, fMapHitstoCATracklet, fBranchMap["STTHit"], fCATrackFinder, fGeometryMap, fMinDistance, fWithCombiReduction);
    // std::cout << "number f triplets: " << tripletIndices.size() << std::endl;
    // for (auto t : tripletIndices)
    //  std::cout << t;

    for (auto triplet : tripletIndices) {
      // Is triplet used is missing here isn't ist?
      LOG(DEBUG) << "Solution for triplet: " << triplet.fTripletHits[0]->GetTubeID() << "/" << triplet.fTripletHits[1]->GetTubeID() << "/" << triplet.fTripletHits[2]->GetTubeID();

      if (fFunc.IsTripletUsed(groupSolutions, triplet)) {
        LOG(DEBUG) << "Triplet used";
        continue;
      }
      // 4. Calculates the Apollonius circles for each triplet (GenerateTripletTracks)
      std::vector<TripletSolution> tripletSolutions;

      tripletSolutions = fFunc.GenerateTripletTracks(triplet, fUnassignedSttHits, fGeometryMap);
#ifdef DEBUGApolloniusTripletFinder
      for (auto solution : tripletSolutions) {
        fTripletTracks.push_back(solution);
      }
#endif
      // 5. Takes only the Apollonius circles which are continuous in the STT (CheckContinuitySolutions)
      fFunc.CheckContinuitySolutions(tripletSolutions, fGeometryMap);
#ifdef DEBUGApolloniusTripletFinder
      for (auto solution : tripletSolutions) {
        fContinuousTripletTracks.push_back(solution);
      }
#endif
      // 6. Hits from other detectors are added to the found apollonius circles (AddOtherDetectors)
      fFunc.AddOtherDetectors(tripletSolutions, fStrawMap, fBranchMap, "STTHit");
#ifdef DEBUGApolloniusTripletFinder
      for (auto solution : tripletSolutions) {
        fTripletTracksAfterAdding.push_back(solution);
      }
#endif
      // 7. Returns only the best solution of the 8 possible apollonoius circles (FindBestSolutions)
      std::vector<TripletSolution> bestSolutions = fFunc.FindBestSolutions(tripletSolutions);
      groupSolutions.insert(groupSolutions.end(), bestSolutions.begin(), bestSolutions.end());
    }
#ifdef DEBUGApolloniusTripletFinder
    LOG(DEBUG) << "Grouped Solutions: ";
    for (auto solution : groupSolutions) {
      LOG(DEBUG) << solution;
    }
#endif
    // 8. Combines identical solutions and reduces the number of tracks to the number of expected tracks in the event (CombineIdenticalSolutions, CheckCombinedSolutions)
    std::vector<TripletSolution> differentSolutions = fFunc.CombineIdenticalSolutions(groupSolutions);
#ifdef DEBUGApolloniusTripletFinder
    LOG(DEBUG) << "Different Solutions: ";
    for (auto solution : differentSolutions) {
      LOG(DEBUG) << solution;
    }
#endif
    int fNExpectedTracks = 1;
    std::vector<TripletSolution> combinedSolutions = fFunc.CheckCombinedSolutions(differentSolutions, fNExpectedTracks);

    LOG(DEBUG) << "Combined Solutions: ";
    for (auto solution : combinedSolutions) {
      solution.SortAllHits(fGeometryMap);
      LOG(DEBUG) << solution;
      fSolutions.push_back(solution);
      // std::cout << "solution: " << solution << std::endl;
      ;
    }
  }
}

// Macro for running Panda simulation  with Geant3 or Geant4
// This macro is supposed to run the full simulation of the panda detector
// to run the macro:
//
// root -l -b -q tut_sim.C 
//
// to run with different options:(e.g more events, different momentum, Geant4)
//
// root -l -b -q 'tut_sim.C(1000,"mydata","mydecay.dec",10.0,"TGeant4")'

void tut_sim(Int_t nEvents = 100,  TString prefix = "signal", TString inputGenerator="pp_jpsi2pi_jpsi_mumu.dec", Double_t BeamMomentum = 6.231552, TString  SimEngine ="TGeant4")
{
	// TString inputGenerator = 
	// EvtGen -> "xxxxxxxx.dec" (parses dec-file for initial particle) or "xxxxxxx.dec:initial_particle"
	// DPM    -> "dpm_xxxxx"
	// FTF    -> "ftf_xxxxx"
	// BOX    -> "box:type(pdgcode,mult):p(min,max):tht(min,max):phi(min,max)"
	// PIPI   -> "pipi:cosTheta(min,max)"
	// LEP    -> "leplep:pid(value):gegm(value):cosTheta(min,max)"

	//----- Other parameter examples for inputGenerator -----------------------
	// inputGenerator = "dpm";
	// inputGenerator = "ftf";
	// inputGenerator = "box:type(211,1):p(1,1):tht(10,120):phi(0,360)";

	//-----User Settings:------------------------------------------------------
	TString parAsciiFile   = "all.par";     // the standard param. file
	TString options        = "pndfiltprim"; // simulation options; pndfiltprim = Use PndFilteredPrimaryGenerator (easier to use) instead FairFilteredPrimaryGenerator
	                                        // "phase1" = phase1 setup; "day1" = day 1 setup; "fakeonline" = smear EMC/tracks momentum
	TString filterconf     = "";            // event filter config; e.g. "(t+-;4..) && M(mu+ mu-; m[3.1,0.6])"

	//-------------------------------------------------------------------------
	// -----   Create the Simulation run manager ------------------------------
	PndMasterRunSim *fRun = new PndMasterRunSim();
	fRun->SetInput(inputGenerator);
	fRun->SetName(SimEngine);
	fRun->SetParamAsciiFile(parAsciiFile);
	fRun->SetNumberOfEvents(nEvents);
	fRun->SetBeamMom(BeamMomentum);
	fRun->SetStoreTraj(kTRUE);
	fRun->SetOptions(options);
	// -----  Initialization   ------------------------------------------------
	fRun->Setup(prefix);
	// -----   Geometry   -----------------------------------------------------
	fRun->CreateGeometry();
	// -----   Event generator   ----------------------------------------------
	fRun->SetGenerator();

	
	// -----   Event filter setup with PndFilteredPrimaryGenerator ------------
	if (options.Contains("pndfiltprim")) {
		PndFilteredPrimaryGenerator* primGen = fRun->GetPndFilteredPrimaryGenerator();
		primGen->SetEventPrintFrequency(100);
		primGen->SetVerbose(filterconf!="" ? 1 : 0);
		if (filterconf!="") primGen->AddFilter(filterconf);
	}
	
	// -----   Example configuration for FairFilteredPrimaryGenerator ---------

	 //FairFilteredPrimaryGenerator *primGen = fRun->GetFilteredPrimaryGenerator();
	 //primGen->SetVerbose(0);

	//FairEvtFilterOnSingleParticleCounts* chrgFilter = new FairEvtFilterOnSingleParticleCounts("chrgFilter");
	//chrgFilter->AndMinCharge(4, FairEvtFilter::kCharged);
	//primGen->AndFilter(chrgFilter);

	//PndEvtFilterOnInvMassCounts *mumuInv = new PndEvtFilterOnInvMassCounts("mumuInvMFilter");
	//mumuInv->SetPdgCodesToCombine(13, -13);
	//mumuInv->SetMinMaxInvMass(2.6, 3.4);
	//mumuInv->SetMinMaxCounts(1, 10000);
	//primGen->AndFilter(mumuInv); // add filter to fFilterList


	// -----   set verbosity level to 0 ---------------------------------------
	if (!options.Contains("pndfiltprim")) 
		fRun->GetFilteredPrimaryGenerator()->SetVerbose(0);	

	// -----   Add tasks   ----------------------------------------------------
	fRun->AddSimTasks();
	// -----   Intialise and run   --------------------------------------------
	fRun->Init();
	fRun->Run(nEvents); 
	fRun->Finish();
}

