// Check if file exists and readable
bool checkfile(TString fn)
{
  bool fileok = true;
  TFile fff(fn, "READ");
  if (fff.IsZombie())
    fileok = false;
  TTree *t = (TTree *)fff.Get("pndsim");
  if (t == nullptr)
    fileok = false;

  if (!fileok)
    cout << "Skipping broken file '" << fn << "'" << endl;
  fff.Close();

  return fileok;
}

// Add many input files to FairRunAna
void attachFiles(FairRunAna *fRun, TString pref, int min, int max)
{
  bool firstfile = true;
  for (int i = min; i <= max; ++i) {
    TString fname = TString::Format("%s_%d_pid.root", pref.Data(), i);

    if (checkfile(fname)) {
      if (firstfile)
        fRun->SetInputFile(fname);
      else
        fRun->AddFile(fname);
      firstfile = false;
    }
  }
}

