//////////////////////////////////////////////////////////////////////////
//                                                                      //
// PndOnlineFilterInfo	                                                //
//                                                                      //
// Information Container for Online Filter Results                      //
//                                                                      //
// Author: Klaus Goetzen, GSI, 2013                                     //
//                                                                      //
//////////////////////////////////////////////////////////////////////////

#include "PndOnlineFilterInfo.h"
#include "TClass.h"
#include <iostream>
#include <stdlib.h>

PndOnlineFilterInfo::PndOnlineFilterInfo() : fTag(false), fNTagTotal(0), fNModes(0)
{
  for (int i = 0; i < OFIMAXMODES; ++i) {
    fMode[i] = -1;
    fNTag[i] = 0;
  }
}

// ---------------------------------------

PndOnlineFilterInfo::~PndOnlineFilterInfo() {}

// ---------------------------------------
// set number of tag candidates for trigger line with code 'mode'
void PndOnlineFilterInfo::SetNTag(int mode, int tag)
{
  for (int i = 0; i < fNModes; ++i) {
    if (fMode[i] == mode) // known mode code
    {
      fNTagTotal = fNTagTotal - fNTag[i] + tag;
      fNTag[i] = tag;
      return;
    }
  }

  // new mode code
  if (fNModes >= OFIMAXMODES) {
    std::cout << "[PndOnlineFilterInfo] **** Exceeding maximum number of " << OFIMAXMODES << " modes!" << std::endl;
    exit(1);
  }

  fMode[fNModes] = mode;
  fNTag[fNModes++] = tag;
  fNTagTotal += tag;
  fTag = (fNTagTotal > 0);
}

// ---------------------------------------
// get number of tag candidates for trigger line with code 'mode'
int PndOnlineFilterInfo::GetNTag(int mode)
{
  for (int i = 0; i < fNModes; ++i)
    if (fMode[i] == mode)
      return fNTag[i];

  return 0;
}

// ---------------------------------------

void PndOnlineFilterInfo::Reset()
{
  fTag = false;
  fNTagTotal = 0;
  fNModes = 0;

  for (int i = 0; i < OFIMAXMODES; ++i) {
    fMode[i] = -1;
    fNTag[i] = 0;
  }
}

// ---------------------------------------

void PndOnlineFilterInfo::Print()
{
  std::cout << "PndOnlineFilterInfo found triggers:   " << std::endl;
  std::cout << "fNTagTotal        : " << fNTagTotal << std::endl;

  for (int i = 0; i < fNModes; ++i) {
    std::cout << "fN[" << fMode[i] << "] :" << fNTag[i] << std::endl;
  }
}

ClassImp(PndOnlineFilterInfo)

// **********************************************************************************************
// Macro for running fast simulation + Software Trigger + simple analysis (PndSimpleCombinerTask)
// **********************************************************************************************

// The parameters are
// -------------------
// quickfsimana.C( <pref>, <decfile>, <mom>, <decay>, [nevt], [res], [parms] )
//    <pref>     : output file names prefix
//    <decfile>  : EvtGen decfile; DPM/FTF/BOX uses DPM/FTF generator (inelastic mode) or box generator instead
//    <mom>      : pbar momentum; negative values are interpreted as -E_cm
//    [decay]    : the decay pattern to be reconstructed, e.g. 'phi -> K+ K-; D_s+ -> phi pi+'; emtpy string: only fast sim will be run
//    [nevt]     : number of events; default = 1000
//    [res]      : resonance/particle type for BOX generator (ignored when running DPM); default = 'pbarpSystem0'
//    [parms]    : parameters for the analysis, e.g. 'mwin=0.4:mwin(phi)=0.1:emin=0.1:pmin=0.1:qamc'
//    [runST]    : if 'true' runs Software Trigger (default: false)
//    [runnum]   : integer run number (default: 0)
//    [mode]     : arbitrary mode number (default: 0)
// -------------------

if (partQA) {
    PndParticleQATask *partQaTask = new PndParticleQATask(fastsim, chrg, neut, mc, mode); // particle QA task
    fRun->AddTask(partQaTask);
  }

  // *****************************
  // *** PndParticleQATask ***
  // *****************************

  // ***********************
  // *** SoftTriggerTask ***
  // ***********************

  if (runST) {
    // this file contains the trigger line definitions
    TString triggercfg = TString(gSystem->Getenv("VMCWORKDIR")) + "/softrig/triggerlines.cfg"; // fullsim trigger definitions
    if (fastsim)
      triggercfg = TString(gSystem->Getenv("VMCWORKDIR")) + "/softrig/triggerlines_fsim.cfg"; // fastsim trigger definitions

    PndSoftTriggerTask *stTask = new PndSoftTriggerTask(Mom, 0, run, triggercfg);

    if (fastsim)
      stTask->SetFastSimDefaults();
    else
      stTask->SetFullSimDefaults();

    fRun->AddTask(stTask);
  }

  // ***********************
  // *** SoftTriggerTask ***
  // ***********************

  // *** and run analysis
  fRun->Init();
  fRun->Run(0, nevts);

  //------------------------Print some info and exit----------------
  fTimer.Stop();
  FairSystemInfo sysInfo;
  Float_t maxMemory = sysInfo.GetMaxMemory();
  Double_t rtime = fTimer.RealTime();
  Double_t ctime = fTimer.CpuTime();

  Float_t cpuUsage = ctime / rtime;

  cout << endl;
  cout << "[INFO   ] Macro call       : prod_ana.C(\"" << prefix << "\", " << from << ", " << to << ", " << mode << ", " << nevts << ")" << endl;
  cout << "[INFO   ] Output file      : " << outFile << endl;
  cout << "[INFO   ] Real time        : " << rtime << " s, CPU time " << ctime << "s" << endl;
  cout << "[INFO   ] CPU usage        : " << cpuUsage * 100. << "%" << endl;
  cout << "[INFO   ] Max Memory       : " << maxMemory << " MB" << endl;
  cout << "[INFO   ] Macro finished successfully." << endl << endl;
  return 0;
}

void quickana(TString Fname = "", double Mom = 0, TString anadecay = "", int nevts = 0, TString anaparms = "", bool fastsim = false, bool runST = false, int run = 0,
              int runmode = 0)
{
  if (Fname == "" || Mom == 0) {
    cout << "USAGE:\n";
    cout << "quickana.C( <input>, <mom>, <decay>, [nevt], [parms], [fastsim], [runST], [runnum], [mode] )\n\n";
    cout << "   <input>   : input file name with PndPidCandidates\n";
    cout << "   <mom>     : pbar momentum; negative values are interpreted as -E_cm\n";
    cout << "   <decay>   : the decay pattern to be reconstructed, e.g. 'phi -> K+ K-; D_s+ -> phi pi-'\n";
    cout << "   [nevt]    : number of events; default: 0 = all\n";
    cout << "   [parms]   : parameters for the analysis, e.g. 'mwin=0.4:mwin(phi)=0.1:emin=0.1:pmin=0.1:qamc'; 'qapart' runs particle QA task\n";
    cout << "   [fastsim] : set true, if running fast sim (sets the PID algos properly); default: false'\n";
    cout << "   [runST]   : if 'true' runs Software Trigger (default: false)\n";
    cout << "   [runnum]  : integer run number (default: 0)\n";
    cout << "   [mode]    : arbitrary mode number (default: 0)\n\n";
    return;
  }

  // do some reconstruction ?
  bool doreco = (anadecay != "" || anaparms.Contains("nevt"));

  // do particle QA?
  bool partQA = (anaparms.Contains("qapart"));
  bool mc = !(anaparms.Contains("!mc")) && !(anaparms.Contains("qamc"));
  bool neut = !(anaparms.Contains("!neut"));
  bool chrg = !(anaparms.Contains("!chrg"));

  // if Mom<0, interprete as -E_cm
  double mp = 0.938272;

  // if mom<0, it's -E_cm -> compute mom
  if (Mom < 0) {
    double X = (Mom * Mom - 2 * mp * mp) / (2 * mp);
    Mom = sqrt(X * X - mp * mp);
  }

  // PID algorithm for the PndSimpleCombinerTask (for Eventshape variables)
  TString pidalgo = "PidAlgoEmcBayes;PidAlgoDrc;PidAlgoDisc;PidAlgoStt;PidAlgoMdtHardCuts;PidAlgoRich;PidAlgoSciT";
  if (fastsim)
    pidalgo = "PidChargedProbability";

  // allow shortcuts
  anadecay.ReplaceAll("pbp", "pbarpSystem");
  anadecay.ReplaceAll("pbp0", "pbarpSystem0");

