  TString pidalgo = "PidAlgoEmcBayes;PidAlgoDrc;PidAlgoDisc;PidAlgoStt;PidAlgoMdtHardCuts";
  if (fastsim)
    pidalgo = "PidChargedProbability";

  // allow shortcuts
  anadecay.ReplaceAll("pbp", "pbarpSystem");
  anadecay.ReplaceAll("pbp0", "pbarpSystem0");

  // Prevent generator from throwing a lot of warnings
  // TLorentzVector fIni(0,0,Mom,0.938272+sqrt(Mom*Mom+0.938272*0.938272));
  TDatabasePDG::Instance()->AddParticle("pbarpSystem", "pbarpSystem", 3, kFALSE, 0.1, 0, "", 88888);
  TDatabasePDG::Instance()->AddParticle("pbarpSystem0", "pbarpSystem0", 3, kFALSE, 0.1, 0, "", 88880);
  TDatabasePDG::Instance()->AddParticle("Z(3900)+", "Z+", 3.900, kFALSE, 0.1, 0, "", 90000);
  TDatabasePDG::Instance()->AddParticle("Z(3900)-", "Z-", 3.900, kFALSE, 0.1, 0, "", -90000);

  // *** set this to your output path
  TString OutFile = Fname(Fname.Last('/') + 1, Fname.Length()); // cut away input path
  OutFile.ReplaceAll(".root", "_ana.root");

  // *** the output file for FairRunAna
  TString InFile = Fname;
  if (!InFile.EndsWith(".root"))
    InFile += "_fast.root";

  // *** initialization
  FairLogger::GetLogger()->SetLogToFile(kFALSE);

  FairRunAna *fRun = new FairRunAna();
  fRun->SetGenerateRunInfo(kFALSE);
  fRun->SetInputFile(InFile);
  fRun->SetOutputFile(OutFile);

  // *** take constant field; needed for PocaVtx
  RhoCalculationTools::ForceConstantBz(20.0);

  // ***********************
  // *** SoftTriggerTask ***
  // ***********************

  if (runST) {
    // this file contains the trigger line definitions
    TString triggercfg = TString(gSystem->Getenv("VMCWORKDIR")) + "/softrig/triggerlines.cfg"; // fullsim trigger definitions
    if (fastsim)
      triggercfg = TString(gSystem->Getenv("VMCWORKDIR")) + "/softrig/triggerlines_fsim.cfg"; // fastsim trigger definitions

    PndSoftTriggerTask *stTask = new PndSoftTriggerTask(Mom, 0, run, triggercfg);

    if (fastsim)
      stTask->SetFastSimDefaults();
    else
      stTask->SetFullSimDefaults();

    fRun->AddTask(stTask);
  }

  // --------------------------------
  // *** Analysis Task ***
  // --------------------------------

  // *****************************
  // *** PndSimpleCombinerTask ***
  // *****************************
  if (fastsim)
    anaparms += ":algo=" + pidalgo;
  PndSimpleCombinerTask *scTask = new PndSimpleCombinerTask(anadecay, anaparms, Mom, run);
  scTask->SetPidAlgo(pidalgo);
  fRun->AddTask(scTask);

  // *** and run analysis
  fRun->Init();
  fRun->Run(0, nevts);
  return 0;
}

InitStatus PndSoftTriggerTask::Init()
{
  fRootManager = FairRootManager::Instance();

  // Register TCA for tagging info
  fTcaOnlineFilterInfo = new TClonesArray("PndOnlineFilterInfo");
  if (fRootManager)
    fRootManager->Register("OnlineFilterInfo", "PndOnlineFolder", fTcaOnlineFilterInfo, kTRUE);

  // *** initialize analysis object
  fAnalysis = new PndAnalysis();
  if (fPhotosMax)
    fAnalysis->McMatchAllowPhotos(fPhotosMax, fPhotosThresh);

  // *** RhoTuple QA helper
  fQA = new PndRhoTupleQA(fAnalysis, fPbarMom);

  // *** Save current gDirectory
//  TDirectory *dir = gDirectory;
//  fRootManager->GetOutFile()->cd();

  FairSink *sink = FairRootManager::Instance()->GetSink();
  if (sink->GetSinkType() == kFILESINK) {
    TDirectory::TContext restorecwd{};
    TFile *outfile = dynamic_cast<FairRootFileSink *>(sink)->GetRootFile();

    // *** create ntuple
    if (fQAEvent) {
      ntp = new RhoTuple("ntpev", "Soft Trigger Common");
      ntp->GetInternalTree()->SetDirectory(outfile);
    }
    if (fQAKs0) {
      nks0 = new RhoTuple("nks0", "K_S -> pi+ pi-");
      nks0->GetInternalTree()->SetDirectory(outfile);
    }
    if (fQAPi0) {
      npi0 = new RhoTuple("npi0", "pi0 -> gamma gamma");
      npi0->GetInternalTree()->SetDirectory(outfile);
    }
    if (fQAEta) {
      neta = new RhoTuple("neta", "eta -> gamma gamma");
      neta->GetInternalTree()->SetDirectory(outfile);
    }
    if (fQAMc) {
      nmc = new RhoTuple("nmc", "MC info");
      nmc->GetInternalTree()->SetDirectory(outfile);
    }
  }

  // *** create mass pre selectors for QA (formular takes into account RhoSelector definition mean +- win/2
  fPi0PreSel = new RhoMassParticleSelector("pi0PreSel", (fPi0QaMax + fPi0QaMin) / 2.0, fPi0QaMax - fPi0QaMin);
  fEtaPreSel = new RhoMassParticleSelector("etaPreSel", (fEtaQaMax + fEtaQaMin) / 2.0, fEtaQaMax - fEtaQaMin);
  fKs0PreSel = new RhoMassParticleSelector("Ks0PreSel", (fKs0QaMax + fKs0QaMin) / 2.0, fKs0QaMax - fKs0QaMin);

  // *** number of sigmas deviation for tag
  // double tagNumSig   = fNsigTag;

  // *** create final selectors for pi0, eta, KS
  fPi0Sel = new RhoMassParticleSelector("pi0Sel", fPi0Mean, fPi0Sigma * 2.0 * fNsigAux);
  fEtaSel = new RhoMassParticleSelector("etaSel", fEtaMean, fEtaSigma * 2.0 * fNsigAux);
  fKs0Sel = new RhoMassParticleSelector("Ks0Sel", fKs0Mean, fKs0Sigma * 2.0 * fNsigAux);

  // *** basic selectors for preselection
  fMomentumSel = new RhoMomentumParticleSelector("PSel", 50. + fTrackMinP, 100.);
  fEnergySel = new RhoEnergyParticleSelector("ESel", 50. + fGammaMinE, 100.);

  // *** the poca vertexer
  fPocaVertexer = new RhoVtxPoca();

  // *** read selection from configuration file
  fSTencode.clear();
  if (fCfgFileName != "" && fApplyFullSelection)
    ReadConfiguration();

  // *** set mode index for current beam momentum
  fSTModeIndex = 0;
  double diff = 1000.;

  for (size_t i = 0; i < fSTencode.size(); ++i) {
    double en = (double)fSTencode[i] / 100.;
    if (fabs(fEcm - en) < diff) {
      diff = fabs(fEcm - en);
      fSTModeIndex = i;
    }
  }

  if (fApplyFullSelection && diff > 1.0)
    cout << "[PndSoftTriggerTask::Init] **** WARNING: Energy of best matching selection differs " << diff << " GeV from current energy!" << endl;

  // *** initialize triggers
  for (TrigIt it = fSTTriggers.begin(); it != fSTTriggers.end(); ++it) {
    PndSoftTriggerLine *tl = it->second;

    if (tl->GetThreshold() <= fEcm) {
      tl->Init();
      if (tl->GetRhoTuple())
        tl->GetRhoTuple()->GetInternalTree()->SetDirectory(gDirectory);

      if (fVerbose > 0) {
        cout << "*** MODE: " << it->first << endl;
        tl->Print();
        cout << endl << endl;
      }
    }
  }

  // *** Resore original gDirectory
//  dir->cd();

